{"actions":[{"action":"success_contract","contract":{"objective":"Start /app/alpine.iso in QEMU in the background so that telnet to 127.0.0.1:6665 reaches the guest login prompt, and leave it running.","required_artifacts":["A running QEMU process using /app/alpine.iso","A reachable telnet service on 127.0.0.1:6665 backed by the guest console"],"required_behaviors":["QEMU starts successfully in the background","Port 6665 on localhost accepts telnet connections","Connecting with telnet shows the guest login prompt","The VM remains running after setup"],"known_invalid_patterns":["Only proving the ISO file exists","Only proving QEMU is installed","Only starting QEMU without confirming the telnet console is reachable","Only checking that port 6665 is open without reaching the login prompt"],"verification_plan":["Inspect the environment for available tools and the ISO path","Start QEMU with a serial console exposed on localhost:6665 and run it in the background","Measure readiness by connecting to 127.0.0.1:6665 and confirming the login prompt appears","Record receipt-backed evidence for the launch command and the successful telnet-visible prompt"],"finalization_evidence_required":["Receipt showing the QEMU launch command completed and the process is running","Receipt showing a telnet connection to 127.0.0.1:6665 reached the guest login prompt"],"notes":["Do not finalize until the telnet-visible login prompt is evidenced."]}},{"action":"plan_update","plan":{"objective":"Start /app/alpine.iso in QEMU in the background so that telnet to 127.0.0.1:6665 reaches the guest login prompt, and leave it running.","current_focus":"Discover available tooling and launch QEMU with a telnet-accessible serial console.","implementation_approach":["Inspect the environment for QEMU/telnet-related tools and confirm the ISO path.","Launch QEMU in the background with a serial console mapped to tcp:127.0.0.1:6665, using a configuration appropriate for Alpine ISO boot.","If needed, iterate on QEMU flags until the telnet connection reaches the login prompt."],"validation_strategy":["Use measured evidence from the launch command/process state.","Connect to 127.0.0.1:6665 and verify the guest login prompt appears."],"verification_test_strategy":["Prefer direct telnet connection evidence over indirect port-open checks.","Avoid treating file existence or process start alone as success."],"known_bad_behavior":["Starting QEMU without exposing a telnet-accessible console.","Stopping after confirming only that the port is open.","Finalizing without receipt-backed evidence of the login prompt."],"evidence_gaps":["No confirmed tool availability yet.","No confirmed QEMU launch command yet.","No confirmed telnet-visible login prompt yet."],"risks":["QEMU may not be installed or may require different console flags.","The ISO may need specific boot parameters or hardware emulation settings."],"next_steps":["Inspect the environment for tools and the ISO file.","Launch QEMU in the background.","Probe telnet readiness and capture prompt evidence."],"finalization_evidence_required":["Receipt showing the QEMU launch command completed and the process is running","Receipt showing a telnet connection to 127.0.0.1:6665 reached the guest login prompt"]}}]}
